import test from 'node:test';
import assert from 'node:assert/strict';
import {DatabaseSync} from 'node:sqlite';
import {readFileSync,readdirSync} from 'node:fs';
import {OrganizationStore} from '../lib/organization-store.js';
import {PrivateTaskStore} from '../lib/private-task-store.js';
function setup(t){const sql=new DatabaseSync(':memory:');t.after(()=>sql.close());for(const f of readdirSync(new URL('../drizzle/',import.meta.url)).filter(x=>x.endsWith('.sql')).sort())sql.exec(readFileSync(new URL('../drizzle/'+f,import.meta.url),'utf8'));
 const db={fail:false,before:null,prepare(s){const make=v=>({s,v,bind:(...a)=>make(a),first:async()=>sql.prepare(s).get(...v)??null,all:async()=>({results:sql.prepare(s).all(...v)})});return make([]);},async batch(items){if(db.before){const f=db.before;db.before=null;await f();}sql.exec('BEGIN');try{const result=items.map((q,i)=>{if(db.fail&&i===1)throw Error('Injected failure');return sql.prepare(q.s).run(...q.v);});sql.exec('COMMIT');return result;}catch(e){sql.exec('ROLLBACK');throw e;}}};return {db,sql,store:new OrganizationStore(db)};}
const org={name:'Synthetic Factory',country:'IT',confirmed:true};
async function create(f){return (await f.store.command('owner','create',org,'create')).organization_id;}
const member=(id,v=0)=>({organization_id:id,member_id:'member',expected_version:v});
test('organisation creation is explicit, idempotent and self-declared; no billing or verification privileges',async t=>{const f=setup(t);await assert.rejects(f.store.command('owner','create',{...org,confirmed:false},'no'),{code:'CONSENT_REQUIRED'});const id=await create(f);assert.equal((await f.store.command('owner','create',org,'create')).organization_id,id);await assert.rejects(f.store.command('owner','create',{...org,name:'Changed'},'create'),{code:'IDEMPOTENCY_CONFLICT'});await assert.rejects(f.store.command('owner','create',org,'again'),{code:'ORGANIZATION_EXISTS'});const list=await f.store.list('owner');assert.equal(list.verification,'SELF_DECLARED');assert.equal(list.billing,'NOT_CONNECTED');assert.equal(list.organizations[0].role,'OWNER');assert.deepEqual((await f.store.list('stranger')).organizations,[]);});
test('membership requires exact recipient acceptance; other actors cannot list or manage memberships',async t=>{const f=setup(t),id=await create(f);await f.store.command('owner','invite',member(id),'invite');assert.equal((await f.store.list('member')).organizations[0].status,'INVITED');for(const a of ['member','stranger'])await assert.rejects(f.store.members(a,id),{code:'ORGANIZATION_UNAVAILABLE'});await assert.rejects(f.store.command('stranger','accept',member(id,1),'accept'),{code:'VERSION_CONFLICT'});await assert.rejects(f.store.command('member','invite',{...member(id),member_id:'stranger'},'bad'),{code:'ORGANIZATION_UNAVAILABLE'});await f.store.command('member','accept',member(id,1),'accept');assert.equal((await f.store.list('member')).organizations[0].status,'ACTIVE');assert.equal((await f.store.members('owner',id)).members[0].actor_id,'member');});
test('revocation beats stale acceptance; reinvitation requires a fresh recipient decision; leaving does not remove owner',async t=>{const f=setup(t),id=await create(f);await f.store.command('owner','invite',member(id),'i');f.db.before=()=>f.store.command('owner','revoke',member(id,1),'r');await assert.rejects(f.store.command('member','accept',member(id,1),'a'),{code:'VERSION_CONFLICT'});assert.deepEqual((await f.store.list('member')).organizations,[]);await f.store.command('owner','invite',member(id,2),'i2');await assert.rejects(f.store.command('member','accept',member(id,1),'a'),{code:'VERSION_CONFLICT'});await f.store.command('member','accept',member(id,3),'a2');await f.store.command('member','leave',member(id,4),'leave');assert.deepEqual((await f.store.list('member')).organizations,[]);await assert.rejects(f.store.command('owner','revoke',{...member(id,1),member_id:'owner'},'owner'),{code:'INVALID_INPUT'});assert.equal((await f.store.list('owner')).organizations[0].role,'OWNER');});
test('organisation state, audit and idempotency writes roll back together',async t=>{const f=setup(t);f.db.fail=true;await assert.rejects(create(f));assert.equal(f.sql.prepare('SELECT count(*) n FROM dossivo_organizations').get().n,0);f.db.fail=false;const id=await create(f);f.db.fail=true;await assert.rejects(f.store.command('owner','invite',member(id),'i'));assert.equal(f.sql.prepare('SELECT count(*) n FROM dossivo_organization_members').get().n,0);assert.equal(f.sql.prepare('SELECT count(*) n FROM dossivo_organization_events').get().n,1);f.db.fail=false;await f.store.command('owner','invite',member(id),'i');assert.equal((await f.store.members('owner',id)).members.length,1);});
test('joining an organisation does not grant access to the creator private tasks',async t=>{const f=setup(t),id=await create(f);await f.store.command('owner','invite',member(id),'i');await f.store.command('member','accept',member(id,1),'a');const tasks=new PrivateTaskStore(f.db);const result=await tasks.command('owner',{action:'create',idempotency_key:'task',data:{synthetic_only:true,purpose:'Private evidence',organization:'Synthetic',facility:'Test',period:'2026-11'}});await assert.rejects(tasks.read('member',result.state.task_id),{code:'TASK_NOT_FOUND'});assert.equal((await tasks.list('member')).length,0);});

import {SubscriptionDrafts,subscriptionQuote} from '../lib/subscription-drafts.js';
const draftData=id=>({organization_id:id,expected_version:0,catalog_version:'2026-11-07.1',plan_id:'starter',cycle:'annual',confirmed:true});
test('subscription preparation computes server prices and refuses price, entitlement and discount injection',()=>{const d=draftData('org');assert.equal(subscriptionQuote(d).amount_minor,49000);assert.equal(subscriptionQuote({...d,cycle:'monthly'}).amount_minor,4900);for(const extra of [{amount_minor:1},{paid:true},{founder:true},{entitlements_activated:true}])assert.throws(()=>subscriptionQuote({...d,...extra}),{code:'INVALID_INPUT'});assert.throws(()=>subscriptionQuote({...d,catalog_version:'old'}),{code:'CATALOG_CHANGED'});assert.throws(()=>subscriptionQuote({...d,plan_id:'enterprise',cycle:'monthly'}),{code:'INVALID_PLAN'});assert.throws(()=>subscriptionQuote({...d,confirmed:false}),{code:'INVALID_INPUT'});const q=subscriptionQuote({...d,plan_id:'enterprise'});assert.equal(q.amount_minor,980000);assert.equal(q.quote_required,true);assert.equal(q.founder_slot_reserved,false);assert.equal(q.evidence_access_granted,false);});
test('subscription preparation belongs to creator, not invited/active members or unrelated accounts',async t=>{const f=setup(t),id=await create(f),billing=new SubscriptionDrafts(f.db);await f.store.command('owner','invite',member(id),'i');await f.store.command('member','accept',member(id,1),'a');for(const actor of ['member','stranger']){await assert.rejects(billing.read(actor,id),{code:'ORGANIZATION_UNAVAILABLE'});await assert.rejects(billing.save(actor,draftData(id),'s'),{code:'ORGANIZATION_UNAVAILABLE'});}const result=await billing.save('owner',draftData(id),'save');assert.equal(result.draft.quote.payment_status,'NOT_CONNECTED');assert.equal(result.draft.quote.entitlements_activated,false);assert.equal((await billing.read('owner',id)).checkout_enabled,false);assert.equal((await f.store.list('owner')).billing,'NOT_CONNECTED');});
test('subscription preparation keeps historical prices, replays safely and refuses concurrent stale replacement',async t=>{const f=setup(t),id=await create(f),billing=new SubscriptionDrafts(f.db),d=draftData(id);const first=await billing.save('owner',d,'s');assert.deepEqual((await billing.save('owner',d,'s')).draft,first.draft);await assert.rejects(billing.save('owner',{...d,plan_id:'business'},'s'),{code:'IDEMPOTENCY_CONFLICT'});await billing.save('owner',{...d,expected_version:1,plan_id:'business'},'s2');await assert.rejects(billing.save('owner',{...d,expected_version:1,plan_id:'export'},'stale'),{code:'VERSION_CONFLICT'});assert.equal((await billing.read('owner',id)).draft.version,2);assert.equal(f.sql.prepare('SELECT count(*) n FROM dossivo_subscription_drafts').get().n,2);assert.equal(JSON.parse(f.sql.prepare('SELECT quote_json FROM dossivo_subscription_drafts WHERE version=1').get().quote_json).amount_minor,49000);});
test('subscription draft transaction failure leaves no saved quote or used request key',async t=>{const f=setup(t),id=await create(f),billing=new SubscriptionDrafts(f.db);f.db.fail=true;await assert.rejects(billing.save('owner',draftData(id),'s'));assert.equal((await billing.read('owner',id)).draft,null);f.db.fail=false;assert.equal((await billing.save('owner',draftData(id),'s')).draft.version,1);});

test('preparation withdrawal appends a version; retries and resume preserve earlier amounts without activating anything',async t=>{const f=setup(t),id=await create(f),b=new SubscriptionDrafts(f.db),d=draftData(id);await b.save('owner',d,'s');const w={organization_id:id,expected_version:1,confirmed:true};const result=await b.withdraw('owner',w,'w');assert.equal(result.draft.version,2);assert.equal(result.draft.quote.status,'WITHDRAWN');assert.equal(result.draft.quote.withdrawn_from_version,1);assert.equal(result.draft.quote.entitlements_activated,false);assert.equal((await b.withdraw('owner',w,'w')).replayed,true);await assert.rejects(b.withdraw('owner',w,'other'),{code:'VERSION_CONFLICT'});await b.save('owner',{...d,expected_version:2,plan_id:'business'},'resume');const h=await b.history('owner',id);assert.deepEqual(h.drafts.map(x=>x.quote.status),['PREPARATION_ONLY','WITHDRAWN','PREPARATION_ONLY']);assert.equal(h.drafts[2].quote.amount_minor,49000);await assert.rejects(b.withdraw('member',{...w,expected_version:3},'x'),{code:'ORGANIZATION_UNAVAILABLE'});});
test('preparation history paginates exact versions, rejects malformed cursor and remains owner scoped',async t=>{const f=setup(t),id=await create(f),b=new SubscriptionDrafts(f.db);for(let i=0;i<52;i++)await b.save('owner',{...draftData(id),expected_version:i},'s'+i);const a=await b.history('owner',id);assert.equal(a.drafts.length,50);const z=await b.history('owner',id,a.next_before);assert.deepEqual(z.drafts.map(x=>x.version),[2,1]);assert.equal(z.next_before,null);for(const cursor of ['-1','x','0','1 OR 1'])await assert.rejects(b.history('owner',id,cursor),{code:'INVALID_INPUT'});await assert.rejects(b.history('stranger',id),{code:'ORGANIZATION_UNAVAILABLE'});});
test('organisation audit exposes scoped event metadata, retains removed members, and paginates timestamp ties',async t=>{const f=setup(t);f.store.clock=()=> '2026-11-07T12:00:00.000Z';const id=await create(f);for(let i=0;i<26;i++){const m={organization_id:id,member_id:'member-'+i,expected_version:0};await f.store.command('owner','invite',m,'i'+i);await f.store.command('owner','revoke',{...m,expected_version:1},'r'+i);}const a=await f.store.audit('owner',id);assert.equal(a.events.length,50);const b=await f.store.audit('owner',id,a.next_before);assert.equal(b.events.length,3);assert.equal(new Set([...a.events,...b.events].map(x=>x.id)).size,53);assert.equal(b.next_before,null);assert.ok(a.events.some(x=>x.action==='revoke'));for(const actor of ['member-1','stranger'])await assert.rejects(f.store.audit(actor,id),{code:'ORGANIZATION_UNAVAILABLE'});assert.ok(!JSON.stringify(a).includes('Synthetic Factory'));await assert.rejects(f.store.audit('owner',id,'{}'),{code:'INVALID_INPUT'});});
test('subscription and membership histories reject update, deletion and replacement via every unique key',async t=>{const f=setup(t),id=await create(f),b=new SubscriptionDrafts(f.db);await b.save('owner',draftData(id),'save');for(const pragma of [0,1]){f.sql.exec('PRAGMA recursive_triggers='+pragma);for(const table of ['dossivo_subscription_drafts','dossivo_organization_events']){assert.throws(()=>f.sql.exec(`UPDATE ${table} SET created_at='changed'`),/HISTORY_APPEND_ONLY/);assert.throws(()=>f.sql.exec(`DELETE FROM ${table}`),/HISTORY_APPEND_ONLY/);assert.throws(()=>f.sql.exec(`INSERT OR REPLACE INTO ${table} SELECT * FROM ${table}`),/HISTORY_APPEND_ONLY/);}assert.throws(()=>f.sql.exec("INSERT OR REPLACE INTO dossivo_subscription_drafts SELECT organization_id,999,actor_id,request_key,command_hash,quote_json,created_at FROM dossivo_subscription_drafts"),/HISTORY_APPEND_ONLY/);}assert.equal((await b.history('owner',id)).drafts.length,1);assert.equal((await f.store.audit('owner',id)).events.length,1);await b.withdraw('owner',{organization_id:id,expected_version:1,confirmed:true},'w');assert.equal((await b.read('owner',id)).draft.version,2);});

import {TestCheckout,checkoutReady} from '../lib/test-checkout.js';
const checkoutConfig={STRIPE_CHECKOUT_MODE:'TEST_ONLY',STRIPE_TEST_SECRET_KEY:'sk_test_SYNTHETIC123456789',STRIPE_WEBHOOK_MODE:'TEST_RECEIPT_ONLY',STRIPE_WEBHOOK_SECRET:'whsec_SYNTHETIC12345678901234567890'};
async function checkoutFixture(t){const f=setup(t),id=await create(f),b=new TestCheckout(f.db);await b.save('owner',draftData(id),'save');return {...f,id,b,data:{organization_id:id,expected_version:1,confirmed:true}};}
function provider(calls,change=x=>x){return async(url,init)=>{calls.push({url,...init});const p=new URLSearchParams(init.body);return Response.json(change({object:'checkout.session',id:'cs_test_synthetic',livemode:false,mode:'subscription',client_reference_id:p.get('client_reference_id'),amount_total:Number(p.get('line_items[0][price_data][unit_amount]')),currency:'eur',expires_at:Number(p.get('expires_at')),url:'https://checkout.stripe.com/c/pay/cs_test_synthetic'}));};}
test('test checkout refuses disabled/live configuration, nonowners and injected amounts before provider calls',async t=>{const f=await checkoutFixture(t),calls=[];assert.equal(checkoutReady({...checkoutConfig,STRIPE_TEST_SECRET_KEY:'sk_live_12345678901234'}),false);await assert.rejects(f.b.create('owner',f.data,'k',{},provider(calls)),{code:'TEST_CHECKOUT_DISABLED'});await assert.rejects(f.b.create('stranger',f.data,'k',checkoutConfig,provider(calls)),{code:'ORGANIZATION_UNAVAILABLE'});await assert.rejects(f.b.create('owner',{...f.data,amount_minor:1},'k',checkoutConfig,provider(calls)),{code:'INVALID_INPUT'});assert.equal(calls.length,0);});
test('test checkout freezes server prices and reuses one session for same draft even with a new request key',async t=>{const f=await checkoutFixture(t),calls=[];const a=await f.b.create('owner',f.data,'k',checkoutConfig,provider(calls)),b=await f.b.create('owner',f.data,'other',checkoutConfig,provider(calls));assert.deepEqual(a,b);assert.equal(calls.length,1);assert.equal(new URLSearchParams(calls[0].body).get('line_items[0][price_data][unit_amount]'),'49000');assert.equal(a.entitlements_activated,false);assert.equal(a.evidence_access_granted,false);assert.equal((await f.b.read('owner',f.id)).draft.quote.payment_status,'NOT_CONNECTED');});
test('provider timeout leaves frozen order and retry uses exact body and idempotency key',async t=>{const f=await checkoutFixture(t),calls=[];await assert.rejects(f.b.create('owner',f.data,'k',checkoutConfig,async(u,i)=>{calls.push({url:u,...i});throw Error('timeout');}),{code:'TEST_PROVIDER_UNAVAILABLE'});await f.b.create('owner',f.data,'k',checkoutConfig,provider(calls));assert.equal(calls[0].body,calls[1].body);assert.equal(calls[0].headers['idempotency-key'],calls[1].headers['idempotency-key']);});
test('test checkout rejects unsafe URLs, live sessions and changed amounts without storing a session',async t=>{const f=await checkoutFixture(t);for(const patch of [{livemode:true},{url:'https://checkout.stripe.com.evil.test/pay'},{url:'https://user@checkout.stripe.com/pay'},{amount_total:1},{client_reference_id:'wrong'}])await assert.rejects(f.b.create('owner',f.data,'k',checkoutConfig,provider([],s=>({...s,...patch}))),{code:'INVALID_TEST_SESSION'});assert.equal(f.sql.prepare('SELECT session_id FROM dossivo_test_checkout_orders').get().session_id,null);});
test('withdrawal during provider request prevents returning checkout URL, preserves reconciliation binding',async t=>{const f=await checkoutFixture(t);await assert.rejects(f.b.create('owner',f.data,'k',checkoutConfig,async(u,i)=>{await f.b.withdraw('owner',f.data,'withdraw');return provider([])(u,i);}),{code:'TEST_CANCELLATION_REQUESTED'});assert.equal(f.sql.prepare('SELECT session_id FROM dossivo_test_checkout_orders').get().session_id,'cs_test_synthetic');await assert.rejects(f.b.create('owner',f.data,'k',checkoutConfig,provider([])),{code:'VERSION_CONFLICT'});});
test('expired test orders cannot create a new provider session with a reused draft',async t=>{const f=await checkoutFixture(t),calls=[];await f.b.create('owner',f.data,'k',checkoutConfig,provider(calls));f.b.clock=()=>new Date(Date.now()+7200000).toISOString();await assert.rejects(f.b.create('owner',f.data,'k',checkoutConfig,provider(calls)),{code:'TEST_SESSION_EXPIRED'});assert.equal(calls.length,1);});
test('provider success followed by database failure recovers with same remote idempotency key',async t=>{const f=await checkoutFixture(t),calls=[],batch=f.db.batch.bind(f.db);let failBind=true;f.db.batch=async items=>{if(failBind&&items[0].s.startsWith('UPDATE dossivo_test_checkout_orders')){failBind=false;throw Error('injected unavailable');}return batch(items);};await assert.rejects(f.b.create('owner',f.data,'k',checkoutConfig,provider(calls)),/injected/);const r=await f.b.create('owner',f.data,'k',checkoutConfig,provider(calls));assert.equal(r.test_only,true);assert.equal(calls.length,2);assert.equal(calls[0].headers['idempotency-key'],calls[1].headers['idempotency-key']);});
test('concurrent checkout requests share a single frozen order and remote idempotency key',async t=>{const f=await checkoutFixture(t),calls=[];const results=await Promise.all(['a','b'].map(k=>f.b.create('owner',f.data,k,checkoutConfig,provider(calls))));assert.equal(results[0].order_id,results[1].order_id);assert.equal(new Set(calls.map(x=>x.headers['idempotency-key'])).size,1);assert.equal(f.sql.prepare('SELECT count(*) n FROM dossivo_test_checkout_orders').get().n,1);});

import {TestPaymentStatus} from '../lib/test-payment-status.js';
import {receivePaymentWebhook} from '../lib/payment-webhook.js';
import {createHmac} from 'node:crypto';
async function signedReceipt(f,{id='evt_test_match',type='checkout.session.completed',session='cs_test_synthetic',patch={},legacy=false,created=100}={}){const order=f.sql.prepare('SELECT id FROM dossivo_test_checkout_orders').get();const body=JSON.stringify({id,object:'event',livemode:false,created,type,data:{object:legacy?{id:session}:{id:session,object:'checkout.session',livemode:false,client_reference_id:order?.id??'unknown',amount_total:49000,currency:'eur',mode:'subscription',payment_status:'paid',customer_email:'PRIVATE_TEST_EMAIL',metadata:{organization_id:'untrusted'},...patch}}});const time=Math.floor(Date.now()/1000),signature=createHmac('sha256',checkoutConfig.STRIPE_WEBHOOK_SECRET).update(time+'.'+body).digest('hex');return receivePaymentWebhook(new Request('https://test/api/payments/stripe-webhook',{method:'POST',body,headers:{'content-type':'application/json','stripe-signature':`t=${time},v1=${signature}`}}),f.db,checkoutConfig);}
const paymentStatus=f=>new TestPaymentStatus(f.db).status('owner',f.id);
test('reconciliation is owner scoped and exposes no checkout URL, provider ID, body or private customer data',async t=>{const f=await checkoutFixture(t);assert.equal((await paymentStatus(f)).status,'NO_TEST_ORDER');await f.b.create('owner',f.data,'k',checkoutConfig,provider([]));await signedReceipt(f);const r=await paymentStatus(f);assert.equal(r.status,'TEST_PAYMENT_MATCHED');assert.equal(r.entitlements_activated,false);assert.equal(r.evidence_access_granted,false);for(const actor of ['member','stranger'])await assert.rejects(new TestPaymentStatus(f.db).status(actor,f.id),{code:'ORGANIZATION_UNAVAILABLE'});for(const secret of ['cs_test','checkout_url','PRIVATE_TEST_EMAIL','untrusted','sk_test','request_body'])assert.ok(!JSON.stringify(r).includes(secret));assert.ok(!JSON.stringify(f.sql.prepare('SELECT * FROM dossivo_payment_test_receipts').all()).includes('PRIVATE_TEST_EMAIL'));assert.equal((await f.b.read('owner',f.id)).draft.quote.payment_status,'NOT_CONNECTED');});
test('completion with unpaid status waits; delayed success and out-of-order completion never regress matched receipt',async t=>{const f=await checkoutFixture(t);await f.b.create('owner',f.data,'k',checkoutConfig,provider([]));assert.equal((await paymentStatus(f)).status,'WAITING_RECEIPT');await signedReceipt(f,{id:'evt_unpaid',patch:{payment_status:'unpaid'}});assert.equal((await paymentStatus(f)).status,'PAYMENT_PENDING');await signedReceipt(f,{id:'evt_paid',type:'checkout.session.async_payment_succeeded'});assert.equal((await paymentStatus(f)).status,'TEST_PAYMENT_MATCHED');await signedReceipt(f,{id:'evt_older',created:10,patch:{payment_status:'unpaid'}});assert.equal((await paymentStatus(f)).status,'TEST_PAYMENT_MATCHED');await signedReceipt(f,{id:'evt_paid',type:'checkout.session.async_payment_succeeded'});assert.equal((await paymentStatus(f)).receipt_count,3);});
test('wrong amount, currency, reference and mode cannot become matched payments',async t=>{for(const patch of [{amount_total:1},{currency:'usd'},{client_reference_id:'another_order'},{mode:'payment'}]){const f=await checkoutFixture(t);await f.b.create('owner',f.data,'k',checkoutConfig,provider([]));await signedReceipt(f,{patch});assert.equal((await paymentStatus(f)).status,'DETAILS_MISMATCH');}});
test('legacy or incomplete snapshots remain review required even when another receipt matches',async t=>{const f=await checkoutFixture(t);await f.b.create('owner',f.data,'k',checkoutConfig,provider([]));await signedReceipt(f,{legacy:true});assert.equal((await paymentStatus(f)).status,'REVIEW_REQUIRED');await signedReceipt(f,{id:'evt_good'});assert.equal((await paymentStatus(f)).status,'REVIEW_REQUIRED');});
test('signed receipt can arrive before provider response is bound; lookup catches up without webhook replay',async t=>{const f=await checkoutFixture(t);await f.b.create('owner',f.data,'k',checkoutConfig,async(u,i)=>{await signedReceipt(f);assert.equal((await paymentStatus(f)).status,'SESSION_NOT_BOUND');return provider([])(u,i);});assert.equal((await paymentStatus(f)).status,'TEST_PAYMENT_MATCHED');});
test('failure and success conflicts stay visible regardless of arrival order',async t=>{const f=await checkoutFixture(t);await f.b.create('owner',f.data,'k',checkoutConfig,provider([]));await signedReceipt(f,{id:'evt_failed',type:'checkout.session.async_payment_failed',patch:{payment_status:'unpaid'}});assert.equal((await paymentStatus(f)).status,'TEST_PAYMENT_FAILED');await signedReceipt(f);assert.equal((await paymentStatus(f)).status,'CONFLICTING_RECEIPTS');});
test('unrelated sessions and invoice events do not match; withdrawn drafts retain a labeled historical test result',async t=>{const f=await checkoutFixture(t);await f.b.create('owner',f.data,'k',checkoutConfig,provider([]));await signedReceipt(f,{id:'evt_other',session:'cs_test_other'});await signedReceipt(f,{id:'evt_invoice',type:'invoice.paid'});assert.equal((await paymentStatus(f)).status,'WAITING_RECEIPT');await signedReceipt(f);await f.b.withdraw('owner',f.data,'withdraw');const r=await paymentStatus(f);assert.equal(r.status,'TEST_PAYMENT_MATCHED');assert.equal(r.draft_current,false);assert.equal(r.draft_version,1);assert.equal(r.entitlements_activated,false);});
test('large receipt histories fail to review instead of choosing a result from a truncated subset',async t=>{const f=await checkoutFixture(t);await f.b.create('owner',f.data,'k',checkoutConfig,provider([]));for(let i=0;i<201;i++)await signedReceipt(f,{id:'evt_many_'+i});const r=await paymentStatus(f);assert.equal(r.status,'REVIEW_REQUIRED');assert.equal(r.receipt_count_capped,true);});

import {TestCheckoutCancellation} from '../lib/test-checkout-cancellation.js';
const cancelData=f=>({organization_id:f.id,draft_version:1,confirmed:true});
function expiryProvider(f,calls,{initial='open',patch={}}={}){return async(url,init)=>{calls.push({url,...init});const o=f.sql.prepare('SELECT * FROM dossivo_test_checkout_orders').get();return Response.json({object:'checkout.session',id:o.session_id,livemode:false,mode:'subscription',client_reference_id:o.id,amount_total:49000,currency:'eur',status:init.method==='POST'?'expired':initial,...patch});};}
test('test stop requires owner, exact order and confirmation; rejects injected provider session',async t=>{const f=await checkoutFixture(t),c=new TestCheckoutCancellation(f.db),calls=[];await f.b.create('owner',f.data,'k',checkoutConfig,provider([]));for(const a of ['member','stranger'])await assert.rejects(c.cancel(a,cancelData(f),checkoutConfig,expiryProvider(f,calls)),{code:'ORGANIZATION_UNAVAILABLE'});await assert.rejects(c.cancel('owner',{...cancelData(f),session_id:'cs_test_other'},checkoutConfig,expiryProvider(f,calls)),{code:'INVALID_INPUT'});await assert.rejects(c.cancel('owner',{...cancelData(f),confirmed:false},checkoutConfig,expiryProvider(f,calls)),{code:'INVALID_INPUT'});assert.equal(calls.length,0);});
test('test stop confirms provider expiry, retries without repeating calls and blocks URL reissue',async t=>{const f=await checkoutFixture(t),c=new TestCheckoutCancellation(f.db),calls=[];await f.b.create('owner',f.data,'k',checkoutConfig,provider([]));const first=await c.cancel('owner',cancelData(f),checkoutConfig,expiryProvider(f,calls));assert.equal(first.cancellation,'EXPIRED_CONFIRMED');assert.equal(calls.length,2);assert.equal(calls[1].method,'POST');assert.ok(calls[1].url.endsWith('/cs_test_synthetic/expire'));assert.deepEqual(await c.cancel('owner',cancelData(f),checkoutConfig,expiryProvider(f,calls)),first);assert.equal(calls.length,2);await assert.rejects(f.b.create('owner',f.data,'again',checkoutConfig,provider([])),{code:'TEST_CANCELLATION_REQUESTED'});assert.equal((await paymentStatus(f)).cancellation,'EXPIRED_CONFIRMED');assert.equal(first.entitlements_activated,false);});
test('timeout keeps durable stop intent and later provider read confirms expiry without another POST',async t=>{const f=await checkoutFixture(t),c=new TestCheckoutCancellation(f.db);await f.b.create('owner',f.data,'k',checkoutConfig,provider([]));await assert.rejects(c.cancel('owner',cancelData(f),checkoutConfig,async()=>{throw Error('timeout');}),{code:'TEST_PROVIDER_UNAVAILABLE'});assert.equal((await paymentStatus(f)).cancellation,'REQUESTED');const calls=[];const result=await c.cancel('owner',cancelData(f),checkoutConfig,expiryProvider(f,calls,{initial:'expired'}));assert.equal(result.cancellation,'EXPIRED_CONFIRMED');assert.equal(calls.length,1);});
test('already completed checkout is review required, never a successful cancellation or refund',async t=>{const f=await checkoutFixture(t),calls=[];await f.b.create('owner',f.data,'k',checkoutConfig,provider([]));const r=await new TestCheckoutCancellation(f.db).cancel('owner',cancelData(f),checkoutConfig,expiryProvider(f,calls,{initial:'complete'}));assert.equal(r.cancellation,'COMPLETED_REVIEW');assert.equal(calls.length,1);assert.equal((await f.b.read('owner',f.id)).draft.quote.entitlements_activated,false);});
test('wrong/live provider expiry responses leave stop pending rather than claiming success',async t=>{for(const patch of [{livemode:true},{id:'cs_test_other'},{amount_total:1},{client_reference_id:'wrong'},{currency:'usd'}]){const f=await checkoutFixture(t);await f.b.create('owner',f.data,'k',checkoutConfig,provider([]));await assert.rejects(new TestCheckoutCancellation(f.db).cancel('owner',cancelData(f),checkoutConfig,expiryProvider(f,[],{patch})),{code:'INVALID_TEST_SESSION'});assert.equal((await paymentStatus(f)).cancellation,'REQUESTED');}});
test('withdrawal persists stop intent atomically even when payment configuration is unavailable',async t=>{const f=await checkoutFixture(t);await f.b.create('owner',f.data,'k',checkoutConfig,provider([]));await f.b.withdraw('owner',f.data,'withdraw');const calls=[];const r=await new TestCheckoutCancellation(f.db).cancel('owner',cancelData(f),{},expiryProvider(f,calls));assert.equal(r.cancellation,'REQUESTED');assert.equal(calls.length,0);const status=await paymentStatus(f);assert.equal(status.draft_current,false);assert.equal(status.pending_cancellations[0].draft_version,1);});
test('in-flight creation after withdrawal binds and expires the remote session without returning its URL',async t=>{const f=await checkoutFixture(t),calls=[];await assert.rejects(f.b.create('owner',f.data,'k',checkoutConfig,async(u,i)=>{if(u.endsWith('/sessions')){await f.b.withdraw('owner',f.data,'withdraw');return provider([])(u,i);}return expiryProvider(f,calls)(u,i);}),{code:'TEST_CANCELLATION_REQUESTED'});assert.equal((await paymentStatus(f)).cancellation,'EXPIRED_CONFIRMED');assert.equal(calls.length,2);});
test('database failure after remote expiry recovers through provider read and preserves original request time',async t=>{const f=await checkoutFixture(t);await f.b.create('owner',f.data,'k',checkoutConfig,provider([]));const c=new TestCheckoutCancellation(f.db),batch=f.db.batch.bind(f.db);let fail=true;f.db.batch=async qs=>{if(fail&&qs[0].s.includes('SET cancel_outcome=')){fail=false;throw Error('db unavailable');}return batch(qs);};await assert.rejects(c.cancel('owner',cancelData(f),checkoutConfig,expiryProvider(f,[])),/db unavailable/);const time=(await paymentStatus(f)).cancel_requested_at;const r=await c.cancel('owner',cancelData(f),checkoutConfig,expiryProvider(f,[],{initial:'expired'}));assert.equal(r.cancellation,'EXPIRED_CONFIRMED');assert.equal(r.requested_at,time);});
test('failed withdrawal transaction leaves neither withdrawn draft nor stop intent',async t=>{const f=await checkoutFixture(t);await f.b.create('owner',f.data,'k',checkoutConfig,provider([]));f.db.fail=true;await assert.rejects(f.b.withdraw('owner',f.data,'withdraw'));f.db.fail=false;assert.equal((await f.b.read('owner',f.id)).draft.version,1);assert.equal((await paymentStatus(f)).cancellation,'NOT_REQUESTED');});
test('unbound and older stop requests remain visible and retryable after a newer preparation exists',async t=>{const f=await checkoutFixture(t);await assert.rejects(f.b.create('owner',f.data,'k',checkoutConfig,async()=>{throw Error();}));const c=new TestCheckoutCancellation(f.db);const r=await c.cancel('owner',cancelData(f),checkoutConfig,async()=>Response.json({object:'list',data:[],has_more:false}));assert.equal(r.cancellation,'REQUESTED');await f.b.save('owner',{...draftData(f.id),expected_version:1},'new');const s=await paymentStatus(f);assert.equal(s.pending_cancellations[0].draft_version,1);assert.equal(s.cancellation,'REQUESTED');assert.equal(s.draft_current,false);});

async function uncertainCheckout(t){const f=await checkoutFixture(t);await assert.rejects(f.b.create('owner',f.data,'k',checkoutConfig,async()=>{throw Error('lost response');}),{code:'TEST_PROVIDER_UNAVAILABLE'});return f;}
function recoverySession(f,patch={}){const o=f.sql.prepare('SELECT * FROM dossivo_test_checkout_orders').get();return {id:'cs_test_recovered',object:'checkout.session',livemode:false,mode:'subscription',client_reference_id:o.id,amount_total:49000,currency:'eur',created:Math.floor(Date.parse(o.created_at)/1000),expires_at:o.expires_at,status:'open',...patch};}
function recoveryProvider(f,calls,list){return async(url,init)=>{calls.push({url,...init});if(url.includes('/sessions?'))return Response.json(typeof list==='function'?list(url):list??{object:'list',data:[recoverySession(f)],has_more:false});return Response.json(recoverySession(f,{status:init.method==='POST'?'expired':'open'}));};}
test('lost creation response recovers unique provider session and expires it without a create POST or URL disclosure',async t=>{const f=await uncertainCheckout(t),calls=[];const r=await new TestCheckoutCancellation(f.db).cancel('owner',cancelData(f),checkoutConfig,recoveryProvider(f,calls));assert.equal(r.cancellation,'EXPIRED_CONFIRMED');assert.equal(calls.length,3);assert.equal(calls[0].method,'GET');assert.ok(calls[0].url.includes('created%5Bgte%5D'));assert.ok(calls[2].url.endsWith('/cs_test_recovered/expire'));assert.ok(calls.every(c=>c.method!=='POST'||c.url.endsWith('/expire')));assert.equal(f.sql.prepare('SELECT checkout_url FROM dossivo_test_checkout_orders').get().checkout_url,null);assert.ok(!JSON.stringify(r).includes('cs_test_recovered'));});
test('recovery waits on no match and succeeds on a later retry with the same durable intent',async t=>{const f=await uncertainCheckout(t),c=new TestCheckoutCancellation(f.db),calls=[];const a=await c.cancel('owner',cancelData(f),checkoutConfig,recoveryProvider(f,calls,{object:'list',data:[],has_more:false}));assert.equal(a.recovery,'NOT_FOUND_YET');assert.equal(a.cancellation,'REQUESTED');const b=await c.cancel('owner',cancelData(f),checkoutConfig,recoveryProvider(f,calls));assert.equal(b.cancellation,'EXPIRED_CONFIRMED');assert.equal(a.requested_at,b.requested_at);});
test('ambiguous or mismatched recovery results cannot bind any provider session',async t=>{for(const patch of [{amount_total:1},{currency:'usd'},{livemode:true},{mode:'payment'},{expires_at:0},{created:0}]){const f=await uncertainCheckout(t);await assert.rejects(new TestCheckoutCancellation(f.db).cancel('owner',cancelData(f),checkoutConfig,recoveryProvider(f,[],{object:'list',data:[recoverySession(f,patch)],has_more:false})),{code:'RECOVERY_REVIEW_REQUIRED'});assert.equal(f.sql.prepare('SELECT session_id FROM dossivo_test_checkout_orders').get().session_id,null);}const f=await uncertainCheckout(t);await assert.rejects(new TestCheckoutCancellation(f.db).cancel('owner',cancelData(f),checkoutConfig,recoveryProvider(f,[],{object:'list',data:[recoverySession(f),recoverySession(f,{id:'cs_test_duplicate'})],has_more:false})),{code:'RECOVERY_REVIEW_REQUIRED'});});
test('bounded recovery pagination finds later match but refuses partial scan even with a candidate',async t=>{const f=await uncertainCheckout(t),calls=[];let page=0;await new TestCheckoutCancellation(f.db).cancel('owner',cancelData(f),checkoutConfig,recoveryProvider(f,calls,()=>++page===1?{object:'list',data:[recoverySession(f,{id:'cs_test_other',client_reference_id:'unrelated'})],has_more:true}:{object:'list',data:[recoverySession(f)],has_more:false}));assert.ok(calls[1].url.includes('starting_after=cs_test_other'));const g=await uncertainCheckout(t);let n=0;await assert.rejects(new TestCheckoutCancellation(g.db).cancel('owner',cancelData(g),checkoutConfig,recoveryProvider(g,[],()=>({object:'list',data:[recoverySession(g,n++?{id:'cs_test_another',client_reference_id:'other'}:{})],has_more:true}))),{code:'RECOVERY_SCAN_LIMIT'});assert.equal(g.sql.prepare('SELECT session_id FROM dossivo_test_checkout_orders').get().session_id,null);});
test('recovery timeout and malformed listing preserve pending state without false cancellation',async t=>{const f=await uncertainCheckout(t),c=new TestCheckoutCancellation(f.db);await assert.rejects(c.cancel('owner',cancelData(f),checkoutConfig,async()=>{throw Error('timeout');}),{code:'TEST_PROVIDER_UNAVAILABLE'});for(const list of [{object:'list',data:[],has_more:true},{object:'list',data:[],has_more:'false'},{object:'other',data:[],has_more:false}])await assert.rejects(c.cancel('owner',cancelData(f),checkoutConfig,recoveryProvider(f,[],list)),{code:'RECOVERY_REVIEW_REQUIRED'});assert.equal((await paymentStatus(f)).cancellation,'REQUESTED');});
test('recovery can bind an already expired or complete session without another remote mutation',async t=>{for(const state of ['expired','complete']){const f=await uncertainCheckout(t),calls=[];const r=await new TestCheckoutCancellation(f.db).cancel('owner',cancelData(f),checkoutConfig,async(url,init)=>{calls.push(init.method);return Response.json(url.includes('/sessions?')?{object:'list',data:[recoverySession(f,{status:state})],has_more:false}:recoverySession(f,{status:state}));});assert.deepEqual(calls,['GET','GET']);assert.equal(r.cancellation,state==='expired'?'EXPIRED_CONFIRMED':'COMPLETED_REVIEW');}});
test('recovery survives local binding failure and concurrent retries converge on one session',async t=>{const f=await uncertainCheckout(t),c=new TestCheckoutCancellation(f.db),batch=f.db.batch.bind(f.db);let fail=true;f.db.batch=async qs=>{if(fail&&qs[0].s.includes('SET session_id=')){fail=false;throw Error('binding unavailable');}return batch(qs);};await assert.rejects(c.cancel('owner',cancelData(f),checkoutConfig,recoveryProvider(f,[])),/binding unavailable/);const outcomes=await Promise.all([1,2].map(()=>c.cancel('owner',cancelData(f),checkoutConfig,recoveryProvider(f,[]))));assert.ok(outcomes.every(r=>r.cancellation==='EXPIRED_CONFIRMED'));assert.equal(f.sql.prepare('SELECT session_id FROM dossivo_test_checkout_orders').get().session_id,'cs_test_recovered');});

import {TestStopWorker,authorizeStopWorker} from '../lib/test-stop-worker.js';
const workerConfig={...checkoutConfig,DOSSIVO_TEST_RETRY_MODE:'TEST_ONLY',DOSSIVO_TEST_RETRY_TOKEN:'SYNTHETIC_SERVICE_TOKEN_12345678901234567890'};
async function queuedStop(t){const f=await checkoutFixture(t);await f.b.create('owner',f.data,'k',checkoutConfig,provider([]));await new TestCheckoutCancellation(f.db).cancel('owner',cancelData(f),{});return f;}
test('stop worker requires dedicated service credential and refuses browser identity, body and query overrides',async()=>{const request=(headers={},suffix='',body)=>new Request('https://test/api/payments/test-stop-worker'+suffix,{method:'POST',headers,...(body?{body}: {})});await assert.rejects(authorizeStopWorker(request(),{}),{code:'TEST_RETRY_DISABLED'});await assert.rejects(authorizeStopWorker(request({'oai-authenticated-user-id':'owner'}),workerConfig),{code:'SERVICE_AUTH_REQUIRED'});await assert.rejects(authorizeStopWorker(request({authorization:'Bearer wrong'}),workerConfig),{code:'SERVICE_AUTH_REQUIRED'});const headers={authorization:'Bearer '+workerConfig.DOSSIVO_TEST_RETRY_TOKEN};await authorizeStopWorker(request(headers),workerConfig);await assert.rejects(authorizeStopWorker(request(headers,'?organization=other'),workerConfig),{code:'INVALID_INPUT'});await assert.rejects(authorizeStopWorker(request(headers,'','{}'),workerConfig),{code:'INVALID_INPUT'});});
test('worker resolves one pending stop, records outcome and ignores terminal work',async t=>{const f=await queuedStop(t),w=new TestStopWorker(f.db),calls=[];const r=await w.run(workerConfig,expiryProvider(f,calls));assert.equal(r.status,'RESOLVED');assert.equal((await w.run(workerConfig,expiryProvider(f,calls))).status,'IDLE');assert.equal(calls.length,2);const audit=f.sql.prepare('SELECT * FROM dossivo_test_stop_attempts').get();assert.equal(audit.outcome,'EXPIRED_CONFIRMED');assert.ok(audit.finished_at);assert.equal((await paymentStatus(f)).retry.attempts,1);assert.equal((await paymentStatus(f)).entitlements_activated,false);assert.ok(!JSON.stringify(r).includes(f.id));});
test('worker backs off transient failures and stops automatically after five attempts',async t=>{const f=await queuedStop(t);let now=Date.now();const w=new TestStopWorker(f.db,{clock:()=>new Date(now).toISOString()});for(let i=1;i<=5;i++){const r=await w.run(workerConfig,async()=>{throw Error('private provider details');});assert.equal(r.status,i===5?'REVIEW_REQUIRED':'RETRY_SCHEDULED');assert.equal((await w.run(workerConfig,async()=>{throw Error('must not call');})).status,'IDLE');now+=60000*2**(i-1)+1;}const row=f.sql.prepare('SELECT retry_attempts,retry_review,retry_last_code FROM dossivo_test_checkout_orders').get();assert.equal(row.retry_attempts,5);assert.equal(row.retry_review,1);assert.equal(row.retry_last_code,'RETRYABLE_FAILURE');assert.equal(f.sql.prepare('SELECT count(*) n FROM dossivo_test_stop_attempts').get().n,5);assert.ok(!JSON.stringify(f.sql.prepare('SELECT * FROM dossivo_test_stop_attempts').all()).includes('private'));});
test('worker sends inconsistent provider results to review without automatic retries',async t=>{const f=await queuedStop(t),w=new TestStopWorker(f.db);assert.equal((await w.run(workerConfig,expiryProvider(f,[],{patch:{livemode:true}}))).status,'REVIEW_REQUIRED');assert.equal((await w.run(workerConfig,expiryProvider(f,[]))).status,'IDLE');assert.equal((await paymentStatus(f)).cancellation,'REQUESTED');});
test('concurrent worker invocation cannot claim an already leased stop',async t=>{const f=await queuedStop(t),w=new TestStopWorker(f.db);let nested;await w.run(workerConfig,async(u,i)=>{nested=await new TestStopWorker(f.db).run(workerConfig,async()=>{throw Error('concurrent network request');});return expiryProvider(f,[])(u,i);});assert.equal(nested.status,'IDLE');assert.equal(f.sql.prepare('SELECT count(*) n FROM dossivo_test_stop_attempts').get().n,1);});
test('expired worker lease is reclaimed and stale attempt remains distinguishable in audit',async t=>{const f=await queuedStop(t),now=Date.now();f.sql.prepare('UPDATE dossivo_test_checkout_orders SET retry_attempts=1,retry_lease_token=?,retry_lease_until=?').run('old_token',now-1);const order=f.sql.prepare('SELECT id FROM dossivo_test_checkout_orders').get();f.sql.prepare('INSERT INTO dossivo_test_stop_attempts(id,order_id,attempt,started_at,outcome) VALUES(?,?,?,?,?)').run('old_token',order.id,1,now-120001,'STARTED');await new TestStopWorker(f.db).run(workerConfig,expiryProvider(f,[]));const rows=f.sql.prepare('SELECT outcome FROM dossivo_test_stop_attempts ORDER BY attempt').all();assert.deepEqual(rows.map(x=>x.outcome),['LEASE_EXPIRED','EXPIRED_CONFIRMED']);});
test('worker claim transaction failure does not spend an attempt or contact provider',async t=>{const f=await queuedStop(t),calls=[];f.db.fail=true;await assert.rejects(new TestStopWorker(f.db).run(workerConfig,expiryProvider(f,calls)));f.db.fail=false;assert.equal(calls.length,0);assert.equal(f.sql.prepare('SELECT retry_attempts FROM dossivo_test_checkout_orders').get().retry_attempts,0);assert.equal(f.sql.prepare('SELECT count(*) n FROM dossivo_test_stop_attempts').get().n,0);});
test('stale worker cannot overwrite retry state after its lease token has been replaced',async t=>{const f=await queuedStop(t),w=new TestStopWorker(f.db);const result=await w.run(workerConfig,async(u,i)=>{const r=await expiryProvider(f,[])(u,i);if(i.method==='POST')f.db.before=()=>{f.sql.prepare('UPDATE dossivo_test_checkout_orders SET retry_lease_token=?,retry_next_at=?').run('replacement_lease',9999999999999);};return r;});assert.equal(result.status,'LEASE_LOST');const row=f.sql.prepare('SELECT retry_lease_token,retry_next_at FROM dossivo_test_checkout_orders').get();assert.equal(row.retry_lease_token,'replacement_lease');assert.equal(row.retry_next_at,9999999999999);});

import {WorkspaceStore} from '../lib/workspace-store.js';
const workspaceRequest={text:'检查本季度工厂证据缺项并持续记录每一份资料的版本',kind:'gap',language:'zh',task_id:null};
test('workspace creates a real private task with bounded automatic title and durable user/result messages',async t=>{const f=setup(t),w=new WorkspaceStore(f.db);const r=await w.execute('owner','request',workspaceRequest,'req');const d=await w.detail('owner',r.task_id);assert.equal(d.meta.title_source,'auto');assert.ok(Array.from(d.meta.title).length<=20);assert.equal(d.messages.length,2);assert.equal(d.results.length,1);assert.equal(d.results[0].body.ai_generated,false);assert.equal(d.results[0].body.scope,'PRIVATE_SYNTHETIC');assert.equal((await w.execute('owner','request',workspaceRequest,'req')).replayed,true);assert.equal((await w.detail('owner',r.task_id)).messages.length,2);await assert.rejects(w.execute('owner','request',{...workspaceRequest,text:'changed'},'req'),{code:'IDEMPOTENCY_CONFLICT'});});
test('workspace cannot read, rename, download snapshots or share another actor task',async t=>{const f=setup(t),w=new WorkspaceStore(f.db),r=await w.execute('owner','request',workspaceRequest,'req');await assert.rejects(w.detail('stranger',r.task_id),{code:'TASK_NOT_FOUND'});await assert.rejects(w.execute('stranger','rename',{task_id:r.task_id,title:'hijack'},'rename'),{code:'TASK_NOT_FOUND'});await assert.rejects(w.execute('stranger','share',{task_id:r.task_id},'share'),{code:'TASK_NOT_FOUND'});assert.equal((await w.listWorkspace('stranger')).tasks.length,0);});
test('workspace task rename, pin and archive persist and are audited; deletion preserves evidence task',async t=>{const f=setup(t),w=new WorkspaceStore(f.db),r=await w.execute('owner','request',workspaceRequest,'req');await w.execute('owner','rename',{task_id:r.task_id,title:'用户命名'},'rename');await w.execute('owner','pin',{task_id:r.task_id,pinned:true},'pin');await w.execute('owner','archive',{task_id:r.task_id},'archive');let list=await w.listWorkspace('owner');assert.equal(list.tasks[0].title,'用户命名');assert.equal(list.tasks[0].pinned,1);assert.ok(list.tasks[0].archived_at);assert.equal(list.tasks[0].title_source,'user');await assert.rejects(w.execute('owner','delete',{task_id:r.task_id},'delete'),{code:'CONFIRM_REQUIRED'});await w.execute('owner','delete',{task_id:r.task_id,confirmed:true},'delete-confirmed');assert.equal((await w.listWorkspace('owner')).tasks.length,0);assert.equal((await new PrivateTaskStore(f.db).read('owner',r.task_id)).task_id,r.task_id);assert.equal(f.sql.prepare('SELECT count(*) n FROM dossivo_workspace_events').get().n,5);assert.equal(f.sql.prepare('SELECT count(*) n FROM dossivo_workspace_results').get().n,1);});
test('result versions are append-only snapshots and survive closing/reopening independently of task updates',async t=>{const f=setup(t),w=new WorkspaceStore(f.db),r=await w.execute('owner','request',workspaceRequest,'req'),first=(await w.detail('owner',r.task_id)).results[0];await w.execute('owner','request',{...workspaceRequest,task_id:r.task_id},'req2');const d=await w.detail('owner',r.task_id);assert.deepEqual(d.results.find(x=>x.id===first.id),first);assert.deepEqual(d.results.map(x=>x.version).sort(),[1,2]);assert.throws(()=>f.sql.exec("UPDATE dossivo_workspace_results SET title='tampered'"),/RESULT_APPEND_ONLY/);assert.throws(()=>f.sql.exec('DELETE FROM dossivo_workspace_results'),/RESULT_APPEND_ONLY/);assert.throws(()=>f.sql.exec('INSERT OR REPLACE INTO dossivo_workspace_results SELECT * FROM dossivo_workspace_results'),/RESULT_APPEND_ONLY/);});
test('workspace preferences are actor scoped and bounded; share endpoint refuses inactive entitlements',async t=>{const f=setup(t),w=new WorkspaceStore(f.db);await w.execute('owner','preferences',{collapsed:1,right_width:620,auto_open:0},'p');assert.equal((await w.listWorkspace('owner')).preferences.right_width,620);assert.equal((await w.listWorkspace('stranger')).preferences.right_width,480);await assert.rejects(w.execute('owner','preferences',{collapsed:1,right_width:900,auto_open:0},'bad'),{code:'INVALID_INPUT'});const r=await w.execute('owner','request',workspaceRequest,'req');await assert.rejects(w.execute('owner','share',{task_id:r.task_id,tier:'restricted',paid:true},'share'),{code:'SHARING_NOT_ENTITLED'});});
test('workspace result/message batch failure does not leave half a result; retry uses original task',async t=>{const f=setup(t),w=new WorkspaceStore(f.db),r=await w.execute('owner','request',workspaceRequest,'req');f.db.fail=true;await assert.rejects(w.execute('owner','request',{...workspaceRequest,task_id:r.task_id},'req2'));f.db.fail=false;assert.equal((await w.detail('owner',r.task_id)).results.length,1);await w.execute('owner','request',{...workspaceRequest,task_id:r.task_id},'req2');assert.equal((await w.detail('owner',r.task_id)).results.length,2);});

test('workspace access audit records successful owner reads without leaking request hashes or other users',async t=>{const f=setup(t),w=new WorkspaceStore(f.db),r=await w.execute('owner','request',workspaceRequest,'a');await w.accessDetail('owner',r.task_id);const log=await w.audit('owner',r.task_id);assert.equal(log.events.length,2);assert.ok(log.events.some(e=>e.action==='task_read'));assert.ok(log.events.every(e=>e.actor==='SELF'&&!('hash' in e)));await assert.rejects(w.accessDetail('stranger',r.task_id),{code:'TASK_NOT_FOUND'});await assert.rejects(w.audit('stranger',r.task_id),{code:'TASK_NOT_FOUND'});assert.equal((await w.audit('owner',r.task_id)).events.length,2);});
test('workspace export returns exact fixed version, audits format and deduplicates retry',async t=>{const f=setup(t),w=new WorkspaceStore(f.db),r=await w.execute('owner','request',workspaceRequest,'a');const original=(await w.detail('owner',r.task_id)).results[0];await w.execute('owner','request',{...workspaceRequest,task_id:r.task_id},'b');const data={task_id:r.task_id,result_id:original.id,format:'docx'};assert.deepEqual((await w.execute('owner','export',data,'x')).result,original);assert.equal((await w.execute('owner','export',data,'x')).replayed,true);const entries=(await w.audit('owner',r.task_id)).events.filter(e=>e.action==='export');assert.equal(entries.length,1);assert.equal(entries[0].version,1);assert.equal(entries[0].format,'docx');await assert.rejects(w.execute('owner','export',{...data,format:'json'},'x'),{code:'IDEMPOTENCY_CONFLICT'});});
test('workspace export refuses cross-task result, altered scope, unknown format and deleted tasks including replay',async t=>{const f=setup(t),w=new WorkspaceStore(f.db),a=await w.execute('owner','request',workspaceRequest,'a'),b=await w.execute('owner','request',workspaceRequest,'b'),d={task_id:a.task_id,result_id:a.result_id,format:'json'};await assert.rejects(w.execute('stranger','export',d,'bad'),{code:'TASK_NOT_FOUND'});await assert.rejects(w.execute('owner','export',{...d,result_id:b.result_id},'bad'),{code:'RESULT_NOT_FOUND'});await assert.rejects(w.execute('owner','export',{...d,scope:'PUBLIC'},'bad'),{code:'INVALID_INPUT'});await assert.rejects(w.execute('owner','export',{...d,format:'html'},'bad'),{code:'INVALID_INPUT'});await w.execute('owner','export',d,'ok');await w.execute('owner','delete',{task_id:a.task_id,confirmed:true},'delete');await assert.rejects(w.execute('owner','export',d,'ok'),{code:'TASK_NOT_FOUND'});});
test('workspace audit paginates stable timestamp ties without duplicates or hidden events',async t=>{const f=setup(t),w=new WorkspaceStore(f.db,{clock:()=> '2026-11-07T12:00:00.000Z'}),r=await w.execute('owner','request',workspaceRequest,'a');for(let i=0;i<55;i++)await w.accessDetail('owner',r.task_id);const first=await w.audit('owner',r.task_id),second=await w.audit('owner',r.task_id,first.next_cursor);assert.equal(first.events.length,50);assert.equal(second.events.length,6);assert.equal(second.next_cursor,null);assert.equal(new Set([...first.events,...second.events].map(e=>e.id)).size,56);await assert.rejects(w.audit('owner',r.task_id,'invalid'),{code:'INVALID_INPUT'});});
test('workspace audit rows resist SQL mutation, deletion and replacement',async t=>{const f=setup(t),w=new WorkspaceStore(f.db);await w.execute('owner','request',workspaceRequest,'a');for(const sql of ["UPDATE dossivo_workspace_events SET action='{}'",'DELETE FROM dossivo_workspace_events','INSERT OR REPLACE INTO dossivo_workspace_events SELECT * FROM dossivo_workspace_events'])assert.throws(()=>f.sql.exec(sql),/WORKSPACE_AUDIT_APPEND_ONLY/);});

test('human revision appends immutable note and lineage without changing evidence snapshot or coverage',async t=>{const f=setup(t),w=new WorkspaceStore(f.db),r=await w.execute('owner','request',workspaceRequest,'r'),before=(await w.detail('owner',r.task_id)).results[0],data={task_id:r.task_id,result_id:before.id,expected_hash:before.hash,note:'合成测试：说明补充安排'};const revised=await w.execute('owner','revise',data,'edit');const detail=await w.detail('owner',r.task_id),after=detail.results.find(x=>x.id===revised.result_id);assert.equal(after.version,2);assert.equal(after.body.user_note,data.note);assert.deepEqual(after.body.coverage,before.body.coverage);assert.equal(after.body.evidence_snapshot_id,before.body.evidence_snapshot_id);assert.equal(after.body.narrative,before.body.narrative);assert.equal(after.body.revision.parent_hash,before.hash);assert.equal(after.body.legal_conclusion,false);assert.equal(after.body.ai_generated,false);assert.deepEqual(detail.results.find(x=>x.id===before.id),before);assert.equal((await w.execute('owner','revise',data,'edit')).replayed,true);assert.equal((await w.detail('owner',r.task_id)).results.length,2);assert.ok((await w.audit('owner',r.task_id)).events.some(x=>x.action==='revise'&&x.version===2));});
test('human revision denies foreign owners, stale versions, hash mismatch and forged coverage/scope',async t=>{const f=setup(t),w=new WorkspaceStore(f.db),r=await w.execute('owner','request',workspaceRequest,'r'),base=(await w.detail('owner',r.task_id)).results[0],d={task_id:r.task_id,result_id:base.id,expected_hash:base.hash,note:'test'};await assert.rejects(w.execute('stranger','revise',d,'edit'),{code:'TASK_NOT_FOUND'});await assert.rejects(w.execute('owner','revise',{...d,scope:'PUBLIC'},'edit'),{code:'INVALID_INPUT'});await assert.rejects(w.execute('owner','revise',{...d,coverage:{percent:100}},'edit'),{code:'INVALID_INPUT'});await assert.rejects(w.execute('owner','revise',{...d,expected_hash:'wrong'},'edit'),{code:'VERSION_CONFLICT'});await w.execute('owner','revise',d,'edit');await assert.rejects(w.execute('owner','revise',d,'stale'),{code:'VERSION_CONFLICT'});});
test('human revision transaction rolls back result message and audit on failure',async t=>{const f=setup(t),w=new WorkspaceStore(f.db),r=await w.execute('owner','request',workspaceRequest,'r'),base=(await w.detail('owner',r.task_id)).results[0],d={task_id:r.task_id,result_id:base.id,expected_hash:base.hash,note:'test'};f.db.fail=true;await assert.rejects(w.execute('owner','revise',d,'edit'));f.db.fail=false;const detail=await w.detail('owner',r.task_id);assert.equal(detail.results.length,1);assert.equal(detail.messages.length,2);assert.equal((await w.audit('owner',r.task_id)).events.length,1);await w.execute('owner','revise',d,'edit');assert.equal((await w.detail('owner',r.task_id)).results.length,2);});
test('concurrent revision detects a new version between read and commit',async t=>{const f=setup(t),w=new WorkspaceStore(f.db),r=await w.execute('owner','request',workspaceRequest,'r'),base=(await w.detail('owner',r.task_id)).results[0],d={task_id:r.task_id,result_id:base.id,expected_hash:base.hash,note:'loser'};f.db.before=()=>w.execute('owner','revise',{...d,note:'winner'},'winner');await assert.rejects(w.execute('owner','revise',d,'loser'),{code:'VERSION_CONFLICT'});const detail=await w.detail('owner',r.task_id);assert.equal(detail.results.length,2);assert.equal(detail.results.find(x=>x.version===2).body.user_note,'winner');});
test('revision length and deleted-task replay remain gated',async t=>{const f=setup(t),w=new WorkspaceStore(f.db),r=await w.execute('owner','request',workspaceRequest,'r'),base=(await w.detail('owner',r.task_id)).results[0],d={task_id:r.task_id,result_id:base.id,expected_hash:base.hash,note:'test'};for(const note of ['', ' '.repeat(3),'a'.repeat(2001)])await assert.rejects(w.execute('owner','revise',{...d,note},'invalid'),{code:'INVALID_INPUT'});await w.execute('owner','revise',d,'edit');await w.execute('owner','delete',{task_id:r.task_id,confirmed:true},'delete');await assert.rejects(w.execute('owner','revise',d,'edit'),{code:'TASK_NOT_FOUND'});});

async function workspaceWithSource(f,mode='SYNTHETIC_TEXT'){const p=new PrivateTaskStore(f.db),w=new WorkspaceStore(f.db);let state=(await p.command('owner',{action:'create',idempotency_key:'source-task',data:{synthetic_only:true,purpose:'Source fixture',organization:'Synthetic',facility:'合成工厂A',period:'2026-10'}})).state;state=(await p.command('owner',{action:'add_material',task_id:state.task_id,expected_version:state.version,idempotency_key:'material',data:mode==='DIRECTORY'?{mode:'DIRECTORY',title:'Synthetic directory',custodian:'Synthetic holder'}:{sample:'normal'}})).state;const r=await w.execute('owner','request',{text:'Prepare evidence',language:'en',kind:'gap',task_id:state.task_id},'source-result');return {w,p,state,r,material:state.materials[0]};}
test('workspace source resolves the historical material and logs metadata without source text',async t=>{const f=setup(t),{w,state,r,material}=await workspaceWithSource(f);const source=await w.resultSource('owner',state.task_id,r.result_id,material.id);assert.equal(source.material.text,material.text);assert.equal(source.material.readable,true);assert.equal(source.task_version,state.version);assert.equal(source.material.original_seen,false);const event=(await w.audit('owner',state.task_id)).events.find(e=>e.action==='source_read');assert.equal(event.version,1);assert.equal(event.result_id,r.result_id);assert.equal('text' in event,false);});
test('workspace historical sources remain fixed after task evidence updates',async t=>{const f=setup(t),{w,p,state,r,material}=await workspaceWithSource(f);const updated=(await p.command('owner',{action:'add_material',task_id:state.task_id,expected_version:state.version,idempotency_key:'more',data:{sample:'missing'}})).state;const source=await w.resultSource('owner',state.task_id,r.result_id,material.id);assert.equal(source.task_version,state.version);assert.equal(source.current_task_version,updated.version);assert.equal(source.material.text,material.text);await assert.rejects(w.resultSource('owner',state.task_id,r.result_id,updated.materials.at(-1).id),{code:'SOURCE_NOT_FOUND'});});
test('workspace cited source rejects foreign actors, missing results and deleted tasks',async t=>{const f=setup(t),{w,state,r,material}=await workspaceWithSource(f);await assert.rejects(w.resultSource('stranger',state.task_id,r.result_id,material.id),{code:'TASK_NOT_FOUND'});await assert.rejects(w.resultSource('owner',state.task_id,'absent',material.id),{code:'SOURCE_NOT_FOUND'});await w.execute('owner','delete',{task_id:state.task_id,confirmed:true},'delete');await assert.rejects(w.resultSource('owner',state.task_id,r.result_id,material.id),{code:'TASK_NOT_FOUND'});});
test('directory source never pretends to contain a readable original',async t=>{const f=setup(t),{w,state,r,material}=await workspaceWithSource(f,'DIRECTORY');const source=await w.resultSource('owner',state.task_id,r.result_id,material.id);assert.equal(source.material.readable,false);assert.equal(source.material.text,null);assert.equal(source.material.original_seen,false);});
test('source read fails closed when its audit cannot be committed',async t=>{const f=setup(t),{w,state,r,material}=await workspaceWithSource(f);f.db.batch=async()=>{throw Error('audit unavailable');};await assert.rejects(w.resultSource('owner',state.task_id,r.result_id,material.id),/audit unavailable/);});

async function addWorkspaceText(p,state,key='intake',extra={}){return p.command('owner',{action:'import_text',task_id:state.task_id,expected_version:state.version,idempotency_key:key,data:{synthetic_only:true,title:'Synthetic electricity note',text:'Synthetic test only: monthly electricity 120 kWh.',categories:['electricity'],facility:state.outcome.facility,period:state.outcome.period,...extra}});}
test('workspace intake refreshes current coverage while preserving the prior result snapshot',async t=>{const f=setup(t),w=new WorkspaceStore(f.db),p=new PrivateTaskStore(f.db),r=await w.execute('owner','request',workspaceRequest,'r'),before=await w.detail('owner',r.task_id);await addWorkspaceText(p,before.state);const current=await w.detail('owner',r.task_id);assert.equal(current.state.version,before.state.version+1);assert.deepEqual(current.results[0],before.results[0]);const next=await w.execute('owner','request',{...workspaceRequest,task_id:r.task_id},'new-result');const result=(await w.detail('owner',r.task_id)).results.find(x=>x.id===next.result_id);assert.equal(result.body.coverage.items.find(x=>x.code==='electricity').submitted,true);assert.equal(result.body.coverage.items.find(x=>x.code==='electricity').company_confirmed,false);assert.equal(result.body.legal_conclusion,false);assert.notEqual(result.body.evidence_snapshot_id,before.results[0].body.evidence_snapshot_id);});
test('workspace intake retry does not duplicate material and stale saves do not overwrite',async t=>{const f=setup(t),w=new WorkspaceStore(f.db),p=new PrivateTaskStore(f.db),r=await w.execute('owner','request',workspaceRequest,'r'),state=(await w.detail('owner',r.task_id)).state;await addWorkspaceText(p,state);assert.equal((await addWorkspaceText(p,state)).replayed,true);assert.equal((await p.read('owner',r.task_id)).materials.length,1);await assert.rejects(addWorkspaceText(p,state,'stale'),{code:'VERSION_CONFLICT'});});
test('workspace missing-material record does not claim submission after regeneration',async t=>{const f=setup(t),w=new WorkspaceStore(f.db),p=new PrivateTaskStore(f.db),r=await w.execute('owner','request',workspaceRequest,'r'),state=(await w.detail('owner',r.task_id)).state;await p.command('owner',{action:'record_material_gap',task_id:r.task_id,expected_version:state.version,idempotency_key:'gap',data:{category:'social_insurance',title:'Synthetic missing social insurance',custodian:'Synthetic HR',reason:'Not received in test'}});const n=await w.execute('owner','request',{...workspaceRequest,task_id:r.task_id},'after-gap'),d=(await w.detail('owner',r.task_id)).results.find(x=>x.id===n.result_id),item=d.body.coverage.items.find(x=>x.code==='social_insurance');assert.equal(item.directory,true);assert.equal(item.submitted,false);assert.equal(item.company_confirmed,false);});
test('workspace intake requires synthetic confirmation and exact task scope for coverage',async t=>{const f=setup(t),w=new WorkspaceStore(f.db),p=new PrivateTaskStore(f.db),r=await w.execute('owner','request',workspaceRequest,'r'),state=(await w.detail('owner',r.task_id)).state;await assert.rejects(addWorkspaceText(p,state,'real',{synthetic_only:false}),{code:'REAL_DATA_DISABLED'});await addWorkspaceText(p,state,'other-scope',{facility:'Different synthetic factory'});const n=await w.execute('owner','request',{...workspaceRequest,task_id:r.task_id},'new');const result=(await w.detail('owner',r.task_id)).results.find(x=>x.id===n.result_id);assert.equal(result.body.coverage.items.find(x=>x.code==='electricity').submitted,false);});

import {ProofVerificationStore,newVerificationCode,normalizeVerificationCode,verificationConfig,signProofToken,verifyProofToken} from '../lib/proof-verification.js';
const verifyEnv={DOSSIVO_OFFICIAL_DOMAIN:'example.org',DOSSIVO_VERIFY_REGION:'eu',DOSSIVO_VERIFY_ACTIVE_KEY:'k1',DOSSIVO_VERIFY_KEYS:JSON.stringify({k1:'a'.repeat(64)}),DOSSIVO_VERIFY_RATE_KEY:'b'.repeat(64)};
const verifySettings=()=>verificationConfig(verifyEnv);
test('verification configuration is fail closed and codes use the prescribed alphabet',()=>{assert.equal(verificationConfig({}),null);assert.equal(verificationConfig({...verifyEnv,DOSSIVO_OFFICIAL_DOMAIN:'https://evil.example/path'}),null);assert.equal(verificationConfig({...verifyEnv,DOSSIVO_VERIFY_KEYS:'{}'}),null);for(let i=0;i<100;i++){const c=newVerificationCode();assert.match(c,/^[ABCDEFGHJKMNPQRSTUVWXYZ23456789]{4}(-[ABCDEFGHJKMNPQRSTUVWXYZ23456789]{4}){2}$/);assert.equal(normalizeVerificationCode(c.toLowerCase()).length,12);}assert.equal(normalizeVerificationCode('OOOO-1111-LLLL'),null);});
test('signed proof tokens reject alteration and retain old verification keys during rotation',async()=>{const c=verifySettings(),id='c'.repeat(32),token=await signProofToken(id,c);assert.equal(await verifyProofToken(token,c),id);for(let i=0;i<token.length;i++){const changed=token.slice(0,i)+(token[i]==='a'?'b':'a')+token.slice(i+1);assert.equal(await verifyProofToken(changed,c),null);}const rotated={...c,kid:'k2',keys:{...c.keys,k2:'d'.repeat(64)}};assert.equal(await verifyProofToken(token,rotated),id);assert.equal(await verifyProofToken(token,{...rotated,region:'us'}),null);});
test('public verification projection contains no evidence, names, relationship, share ID or full snapshot hash',async t=>{const f=setup(t),w=new ProofVerificationStore(f.db),c=verifySettings(),r=await w.register({buyer:'PRIVATE_BUYER',supplier:'PRIVATE_SUPPLIER',evidence:'PRIVATE_EVIDENCE'},{shareId:'private-share',expiresAt:'2030-01-01T00:00:00Z',layer:'AUTHORIZED'},c);const result=await w.lookup(r.code,'10.0.0.1',c);assert.equal(result.status,'ACTIVE');assert.equal(result.content_fingerprint,r.content_fingerprint);assert.deepEqual(Object.keys(result).sort(),['content_fingerprint','created_at','expires_at','layer','status']);assert.doesNotMatch(JSON.stringify(result),/PRIVATE_|private-share/);assert.equal((await w.lookup('AAAA-BBBB-CCCC','10.0.0.1',c)).status,'NOT_FOUND');});
test('revoked and expired verification records disclose only status and date',async t=>{const f=setup(t),c=verifySettings(),w=new ProofVerificationStore(f.db,{clock:()=> '2026-11-07T00:00:00Z'}),r=await w.register({x:1},{shareId:'s',expiresAt:'2026-11-08T00:00:00Z',layer:'PUBLIC'},c);const later=new ProofVerificationStore(f.db,{clock:()=> '2026-11-09T00:00:00Z'});assert.deepEqual(await later.lookup(r.code,'10.0.0.1',c),{status:'EXPIRED',date:'2026-11-08T00:00:00.000Z'});f.sql.prepare('UPDATE dossivo_proof_verifications SET revoked_at=? WHERE share_id=?').run('2026-11-07T01:00:00Z','s');assert.deepEqual(await later.lookup(r.code,'10.0.0.2',c),{status:'REVOKED',date:'2026-11-07T01:00:00Z'});assert.throws(()=>f.sql.exec('UPDATE dossivo_proof_verifications SET revoked_at=NULL'),/VERIFICATION_IMMUTABLE/);assert.throws(()=>f.sql.exec("UPDATE dossivo_proof_verifications SET snapshot_hash='tampered'"),/VERIFICATION_IMMUTABLE/);});
test('verification rate limits reject the eleventh IP query and thirty-first code query',async t=>{const f=setup(t),c=verifySettings(),w=new ProofVerificationStore(f.db,{clock:()=> '2026-11-07T00:00:00Z'});for(let i=0;i<10;i++)await w.lookup(newVerificationCode(),'10.0.0.1',c);await assert.rejects(w.lookup(newVerificationCode(),'10.0.0.1',c),{code:'RATE_LIMITED'});const code=newVerificationCode();for(let i=0;i<30;i++)await w.lookup(code,'10.1.0.'+i,c);await assert.rejects(w.lookup(code,'10.2.0.1',c),{code:'RATE_LIMITED'});await assert.rejects(w.lookup(code,null,c),{code:'VERIFY_UNAVAILABLE'});});
test('new verification snapshots get independent codes and do not overwrite earlier records',async t=>{const f=setup(t),c=verifySettings(),w=new ProofVerificationStore(f.db),a=await w.register({version:1},{shareId:'s1',expiresAt:'2030-01-01T00:00:00Z',layer:'PUBLIC'},c),b=await w.register({version:2},{shareId:'s2',expiresAt:'2030-01-01T00:00:00Z',layer:'PUBLIC'},c);assert.notEqual(a.code,b.code);assert.notEqual(a.content_fingerprint,b.content_fingerprint);assert.equal((await w.lookup(a.code,'10.0.0.1',c)).content_fingerprint,a.content_fingerprint);assert.throws(()=>f.sql.exec('DELETE FROM dossivo_proof_verifications'),/VERIFICATION_IMMUTABLE/);});

function legacyProofFixture(f){const now='2026-11-07T00:00:00.000Z';f.sql.prepare('INSERT INTO outcome_cases(id,tenant_id,title,state_json,created_at,updated_at) VALUES(?,?,?,?,?,?)').run('legacy-case','owner','Synthetic','{}',now,now);f.sql.prepare('INSERT INTO proof_links(token,case_id,recipient,expires_at,remaining_views,card_version,card_snapshot_json,scope_snapshot_json,created_at) VALUES(?,?,?,?,?,?,?,?,?)').run('d'.repeat(32),'legacy-case','PRIVATE_BUYER','2030-01-01T00:00:00.000Z',3,1,JSON.stringify({en:{title:'Synthetic'}}),JSON.stringify({facility:'PRIVATE_FACILITY',period:'2026-11'}),now);return 'd'.repeat(32);}
test('verification binding requires source owner and resolves signed tokens without consuming views',async t=>{const f=setup(t),token=legacyProofFixture(f),w=new ProofVerificationStore(f.db),c=verifySettings();await assert.rejects(w.bindExistingProof('other',token,c),{code:'SOURCE_UNAVAILABLE'});const r=await w.bindExistingProof('owner',token,c);assert.equal(await w.resolveSignedProof(r.token,c),token);assert.equal((await w.lookup(r.code,'10.0.0.1',c)).status,'ACTIVE');assert.equal(f.sql.prepare('SELECT remaining_views n FROM proof_links').get().n,3);assert.deepEqual(await w.bindExistingProof('owner',token,c),r);});
test('verification status tracks original link revocation and hides metadata',async t=>{const f=setup(t),token=legacyProofFixture(f),w=new ProofVerificationStore(f.db),c=verifySettings(),r=await w.bindExistingProof('owner',token,c);f.sql.prepare('UPDATE proof_links SET revoked_at=?').run('2026-11-07T03:00:00Z');assert.deepEqual(await w.lookup(r.code,'10.0.0.1',c),{status:'REVOKED',date:'2026-11-07T03:00:00Z'});assert.equal(await w.resolveSignedProof(r.token,c),null);});
test('verification status tracks exhausted access without granting extra visits',async t=>{const f=setup(t),token=legacyProofFixture(f),w=new ProofVerificationStore(f.db),c=verifySettings(),r=await w.bindExistingProof('owner',token,c);f.sql.exec('UPDATE proof_links SET remaining_views=0');assert.deepEqual(await w.lookup(r.code,'10.0.0.1',c),{status:'EXHAUSTED'});assert.equal(await w.resolveSignedProof(r.token,c),null);assert.equal(f.sql.prepare('SELECT remaining_views n FROM proof_links').get().n,0);});
test('verification refuses a changed or missing source snapshot',async t=>{const f=setup(t),token=legacyProofFixture(f),w=new ProofVerificationStore(f.db),c=verifySettings(),r=await w.bindExistingProof('owner',token,c);assert.throws(()=>f.sql.prepare('UPDATE proof_links SET card_snapshot_json=?').run('{"en":{"title":"tampered"}}'),/BOUND_PROOF_IMMUTABLE/);f.sql.exec('DELETE FROM outcome_cases');assert.deepEqual(await w.lookup(r.code,'10.0.0.1',c),{status:'SOURCE_UNAVAILABLE'});});
test('binding transaction detects revocation race and rolls back partial registry inserts',async t=>{const f=setup(t),token=legacyProofFixture(f),w=new ProofVerificationStore(f.db),c=verifySettings();f.db.before=()=>f.sql.prepare('UPDATE proof_links SET revoked_at=?').run('2026-11-07T03:00:00Z');await assert.rejects(w.bindExistingProof('owner',token,c),{code:'SOURCE_CONFLICT'});assert.equal(f.sql.prepare('SELECT count(*) n FROM dossivo_proof_verifications').get().n,0);f.sql.exec('UPDATE proof_links SET revoked_at=NULL');f.db.fail=true;await assert.rejects(w.bindExistingProof('owner',token,c));assert.equal(f.sql.prepare('SELECT count(*) n FROM dossivo_proof_verification_bindings').get().n,0);});
test('binding cannot be reassigned and signed resolution rejects tampering',async t=>{const f=setup(t),token=legacyProofFixture(f),w=new ProofVerificationStore(f.db),c=verifySettings(),r=await w.bindExistingProof('owner',token,c);assert.equal(await w.resolveSignedProof(r.token+'a',c),null);assert.throws(()=>f.sql.exec("UPDATE dossivo_proof_verification_bindings SET proof_token='other'"),/PROOF_BINDING_IMMUTABLE/);assert.throws(()=>f.sql.exec('DELETE FROM dossivo_proof_verification_bindings'),/PROOF_BINDING_IMMUTABLE/);const later=new ProofVerificationStore(f.db,{clock:()=> '2031-01-01T00:00:00Z'});assert.equal((await later.lookup(r.code,'10.0.0.1',c)).status,'EXPIRED');assert.equal(await later.resolveSignedProof(r.token,c),null);});
test('public verification mode refuses unbound internal registry fixtures',async t=>{const f=setup(t),c=verifySettings(),w=new ProofVerificationStore(f.db),r=await w.register({test:true},{shareId:'unbound',expiresAt:'2030-01-01T00:00:00Z',layer:'AUTHORIZED'},c);assert.deepEqual(await w.lookup(r.code,'10.0.0.1',c,true),{status:'SOURCE_UNAVAILABLE'});});
test('issuance recovery survives service restart and retained-key rotation without storing plaintext',async t=>{const f=setup(t),token=legacyProofFixture(f),c=verifySettings(),r=await new ProofVerificationStore(f.db).bindExistingProof('owner',token,c);const rotated={...c,kid:'k2',keys:{...c.keys,k2:'c'.repeat(64)}};assert.deepEqual(await new ProofVerificationStore(f.db).bindExistingProof('owner',token,rotated),r);assert.equal(f.sql.prepare('SELECT count(*) n FROM dossivo_proof_verifications').get().n,1);assert.equal(f.sql.prepare('SELECT remaining_views n FROM proof_links').get().n,3);assert.doesNotMatch(JSON.stringify(f.sql.prepare('SELECT * FROM dossivo_proof_issuance_receipts').get()),new RegExp(r.code));});
test('issuance recovery fails closed for wrong owner, revoked registry and exhausted source',async t=>{const f=setup(t),token=legacyProofFixture(f),c=verifySettings(),w=new ProofVerificationStore(f.db);await w.bindExistingProof('owner',token,c);await assert.rejects(w.bindExistingProof('stranger',token,c),{code:'SOURCE_UNAVAILABLE'});f.sql.exec('UPDATE proof_links SET remaining_views=0');await assert.rejects(w.bindExistingProof('owner',token,c),{code:'SOURCE_UNAVAILABLE'});f.sql.exec("UPDATE proof_links SET remaining_views=3; UPDATE dossivo_proof_verifications SET revoked_at='2026-11-07'");await assert.rejects(w.bindExistingProof('owner',token,c),{code:'SOURCE_UNAVAILABLE'});});
test('issuance recovery rejects missing or replaced original keys, domain and region changes',async t=>{const f=setup(t),token=legacyProofFixture(f),c=verifySettings(),w=new ProofVerificationStore(f.db);await w.bindExistingProof('owner',token,c);for(const changed of [{...c,keys:{}},{...c,keys:{[c.kid]:'c'.repeat(64)}},{...c,domain:'different.example.org'},{...c,region:'us'}])await assert.rejects(w.bindExistingProof('owner',token,changed),{code:'RECOVERY_UNAVAILABLE'});assert.equal(f.sql.prepare('SELECT count(*) n FROM dossivo_proof_verifications').get().n,1);});
test('concurrent issuance retries converge on one immutable receipt',async t=>{const f=setup(t),token=legacyProofFixture(f),c=verifySettings(),w=new ProofVerificationStore(f.db);const [a,b]=await Promise.all([w.bindExistingProof('owner',token,c),w.bindExistingProof('owner',token,c)]);assert.deepEqual(a,b);assert.equal(f.sql.prepare('SELECT count(*) n FROM dossivo_proof_issuance_receipts').get().n,1);assert.throws(()=>f.sql.exec("UPDATE dossivo_proof_issuance_receipts SET key_id='changed'"),/PROOF_RECEIPT_IMMUTABLE/);assert.throws(()=>f.sql.exec('DELETE FROM dossivo_proof_issuance_receipts'),/PROOF_RECEIPT_IMMUTABLE/);assert.throws(()=>f.sql.exec('INSERT OR REPLACE INTO dossivo_proof_issuance_receipts SELECT * FROM dossivo_proof_issuance_receipts'),/PROOF_RECEIPT_IMMUTABLE/);});
test('older bindings without receipts cannot silently receive new codes',async t=>{const f=setup(t),token=legacyProofFixture(f),c=verifySettings(),w=new ProofVerificationStore(f.db);await w.bindExistingProof('owner',token,c);f.sql.exec('DROP TRIGGER proof_receipt_no_delete; DELETE FROM dossivo_proof_issuance_receipts');await assert.rejects(w.bindExistingProof('owner',token,c),{code:'RECOVERY_UNAVAILABLE'});assert.equal(f.sql.prepare('SELECT count(*) n FROM dossivo_proof_verifications').get().n,1);});
